def build_plan(n, links, caps, parts, r):
    D = sum(r.values())
    if D <= 0:
        return None
    dist = participant_distance(n, links, parts, caps)
    plan = _greedy_plan(n, links, caps, parts, r, dist)
    if plan is not None:
        return plan
    for strat in ('bfs', 'star', 'chain'):
        trees = _make_trees(strat, parts, dist)
        if trees is None:
            continue
        plan = _route_trees(n, links, caps, parts, r, trees)
        if plan is not None:
            return plan
    return None


def _adjacency(n, links, caps, parts):
    C = set([v for (v, _rv) in parts])
    adj = defaultdict(list)
    for l, (a, b) in enumerate(links):
        if caps[l] <= 0:
            continue
        adj[a].append((b, 2 * l))
        adj[b].append((a, 2 * l + 1))
    return adj, C


def _bfs_order(adj, C, src):
    seen = {src}
    order = [src]
    q = deque([src])
    while q:
        x = q.popleft()
        if x in C and x != src:
            continue
        for (y, _a) in adj[x]:
            if y not in seen:
                seen.add(y)
                order.append(y)
                q.append(y)
    return [v for v in order if v in C]


def _greedy_plan(n, links, caps, parts, r, dist):
    adj, C = _adjacency(n, links, caps, parts)
    router = Router(n, links, caps)
    routes = []
    recipes = []
    memo = {}
    Lv = {}          # origin -> defaultdict pair -> amount
    origins = sorted([p for p in parts if p[1] > 0], key=lambda p: -p[1])
    for (v, rv) in origins:
        order = _bfs_order(adj, C, v)
        if len(order) != len(C):
            return None
        lv = defaultdict(int)
        connected = set([v])
        pairflows = defaultdict(list)
        for w in order:
            if w == v:
                continue
            remaining = rv
            senders = sorted(connected, key=lambda u: (dist[(u, w)], u))
            for u in senders:
                if remaining <= 0:
                    break
                allowed = set(range(n)) - (C - set([u, w]))
                fl = router.route_max(u, w, remaining, allowed)
                if fl is None:
                    continue
                got = 0
                for (path, cnt) in fl:
                    rid = _recipe(path, recipes, memo)
                    if rid is None:
                        return None
                    pairflows[(u, w)].append((cnt, rid))
                    got += cnt
                if got > 0:
                    lv[(u, w)] += got
                    remaining -= got
            if remaining > 0:
                return None
            connected.add(w)
        Lv[v] = (lv, pairflows)
    trees = []
    for (v, rv) in origins:
        lv, _pf = Lv[v]
        recs = _decompose_trees(v, rv, lv, parts)
        if recs is None:
            return None
        trees.extend(recs)
    for (v, rv) in origins:
        _pf = Lv[v][1]
        for (key, lst) in _pf.items():
            for (cnt, rid) in lst:
                routes.append([key[0], key[1], cnt, rid])
    return {'trees': trees, 'routes': routes, 'recipes': recipes}


def _decompose_trees(root, total, lv, parts):
    """Split the pair-demand dict lv (sum over in-degrees == total per node)
    into arborescence records rooted at `root`."""
    C = [v for (v, _rv) in parts]
    work = defaultdict(int)
    for k, val in lv.items():
        if val > 0:
            work[k] = val
    recs = []
    left = total
    adj, _ = None, None
    order_cache = {}
    guard = 0
    while left > 0:
        guard += 1
        if guard > 4000 or len(recs) > 8000:
            return None
        # greedy parent assignment in BFS-ish order from root
        order = [root] + [w for w in C if w != root]
        parents = {}
        for w in order:
            if w == root:
                continue
            best = None
            for u in order:
                if u == w or u not in order[:order.index(w)]:
                    continue
                if work.get((u, w), 0) > 0:
                    if best is None:
                        best = u
            if best is None:
                return None
            parents[w] = best
        cnt = min([work[(parents[w], w)] for w in parents] + [left])
        if cnt <= 0:
            return None
        edges = [[parents[w], w] for w in parents]
        recs.append([root, cnt, edges])
        for w in parents:
            work[(parents[w], w)] -= cnt
        left -= cnt
    if left != 0:
        return None
    return recs


def _make_trees(strat, parts, dist):
    trees = []
    C = [v for (v, rv) in parts]
    for (v, rv) in parts:
        if rv <= 0:
            continue
        if strat == 'star':
            edges = [[v, w] for w in C if w != v]
        elif strat == 'bfs':
            order = sorted([w for w in C if w != v],
                           key=lambda w: (dist[(v, w)], w))
            placed = set([v])
            edges = []
            for w in order:
                best = None
                for u in placed:
                    d = dist[(u, w)]
                    if d == float('inf'):
                        continue
                    if best is None or d < best[0]:
                        best = (d, u)
                if best is None:
                    return None
                edges.append([best[1], w])
                placed.add(w)
        else:  # chain
            order = [v] + sorted([w for w in C if w != v],
                                 key=lambda w: (dist[(v, w)], w))
            edges = []
            prev = None
            for w in order:
                if prev is None:
                    prev = w
                    continue
                edges.append([prev, w])
                prev = w
        trees.append([v, rv, edges])
    return trees


def _route_trees(n, links, caps, parts, r, trees):
    C = set([v for (v, _rv) in parts])
    L = defaultdict(int)
    for (root, cnt, edges) in trees:
        for (u, w) in edges:
            L[(u, w)] += cnt
    if not L:
        return {'trees': trees, 'routes': [], 'recipes': []}
    router = Router(n, links, caps)
    routes = []
    recipes = []
    memo = {}
    order = sorted(L.items(), key=lambda kv: -kv[1])
    for ((u, w), amt) in order:
        allowed = set(range(n)) - (C - set([u, w]))
        fl = router.route(u, w, amt, allowed)
        if fl is None:
            return None
        for (path, cnt) in fl:
            rid = _recipe(path, recipes, memo)
            if rid is None:
                return None
            routes.append([u, w, cnt, rid])
    return {'trees': trees, 'routes': routes, 'recipes': recipes}


